import {esc,para,title,code,answer,tab,treeDrawing,recurrence,lcs,matrixChain,knapsack,huffman,partition,heapify,graphDrawing,spanning,dijkstra,floyd,activities,traverse} from './algorithms.mjs';
export const QS=[],DIAGRAMS=[];
let paper='E1',long=4;
function add(ref,topic,page,question,solution,why){
  const id=paper+'-'+ref, qhtml=para(esc(question));
  const marks=ref.startsWith('1(')?1:paper==='E5'&&/^[23]\(a\)$/.test(ref)?6:paper==='E5'&&/^[23]\(b\)$/.test(ref)?4:long;
  const result=typeof solution==='string'?{html:why?answer(solution,why):para(solution)}:solution;
  const ahtml=result.html,plain=ahtml.replace(/<[^>]*>/g,' ');
  QS.push({id,paper,ref,topic,marks,page,question,qhtml,ahtml,solution:plain,steps:result.steps});
  if(result.diagram) DIAGRAMS.push({id,title:result.diagramTitle??question,label:result.diagram.match(/<figcaption>[\s\S]*?<strong>([^<]+)/)?.[1]??question,topic,ref:id,html:result.diagram,steps:result.steps});
}
const A='Analysis',R='Recurrences',S='Sorting',D='Dynamic',G='Greedy',H='Graphs',M='Amortized',C='Complexity';
const letters='abcdefghijklmnopqrstuvwxyz';
const arr=[98,87,76,65,54,43,32,21,10];
const compact=(s)=>s.split(' ').map(t=>[t[0],t[1],+t.slice(2)]);
const arrows=(s)=>s.split(' ').map(t=>[t[0],t[1]]);
const kth='Compare with pivot rank, then continue only in the side containing the target. For kth largest, the zero-based ascending rank is n−k. Randomized Quickselect takes expected Θ(n), worst Θ(n²). Median of medians guarantees Θ(n).';
const types=tab(['Class','Membership test or condition','Example'],[['P','Decision problem solvable in deterministic polynomial time','Graph reachability'],['NP','YES certificate verified in deterministic polynomial time','CLIQUE'],['NP-hard','All NP languages reduce to it in polynomial time','Optimization TSP'],['NP-complete','Both in NP and NP-hard','3-SAT']]);
const np=answer('P ⊆ NP · NP-complete = NP ∩ NP-hard','A solver for a P problem can also verify membership in polynomial time. NP-hardness compares problems via polynomial many-one reductions. A polynomial-time algorithm for any NP-complete problem would imply P=NP.')+types;
const clique=answer('CLIQUE ∈ NP','The decision instance is a graph G and integer k. A YES certificate lists k distinct vertices. Verify that all are valid vertices and each of the k(k−1)/2 unordered pairs is adjacent.')+code('verify(G, k, S):\n  if k < 0 or k > |V| or |S| != k: return false\n  if S contains a duplicate or nonvertex: return false\n  for each unordered pair {u,v} in S:\n    if !G[u][v]: return false\n  return true')+para('Verification takes O(k²+V) with an adjacency matrix and a direct-index seen array. If an instance has a clique of size at least k, any k members form a valid certificate.');
const lv=tab(['Randomized class','Correctness','Time','Example'],[['Las Vegas','Always correct when it returns','May vary with random choices','Randomized quicksort'],['Monte Carlo','Can err with bounded probability','Usually fixed or bounded for a chosen error budget','Miller–Rabin with fixed rounds']]);
const floydName='Floyd–Warshall. Its state permits a growing set of intermediate vertices. Each update compares the previous route with the route through the new vertex.';
const strategy=tab(['Aspect','Divide and conquer','Dynamic programming'],[['Subproblems','Typically independent','Typically overlap'],['Use of results','Solve and combine','Cache each state and reuse'],['Example','Merge sort, binary search','LCS, matrix-chain ordering']])+para('Both decompose a problem and combine results. For optimization, prove optimal substructure: the parts of an optimal solution must be optimal for their corresponding states.');
const am=answer('Θ(1) amortized per operation','For m = ⌊log₂ n⌋, all expensive operation costs sum to 1+2+4+…+2ᵐ = 2ᵐ⁺¹−1 < 2n. Other operations contribute at most n. Total cost is less than 3n and at least n, even though a single operation can cost Θ(n).');
const constantTree=()=>recurrence({a:3,b:3,toll:'6',caption:'Three calls with constant local work',result:'T(n) = 3(n−1) · Θ(n)',reason:'Let n = 3ᵐ. Level d has 3ᵈ nodes and each internal node contributes 6. Sum 6(1+3+…+3ᵐ⁻¹) = 3(3ᵐ−1). All n leaves cost zero.',levels:[[0,1,6],[1,3,18],[2,9,54],['d','3ᵈ','6·3ᵈ'],['m','n','0 (base)']]});
const uneven=(x,y,upper=false)=>recurrence({factors:[[1,x],[y,x]],toll:upper?'O(n)':'n',caption:'Unequal subproblem sizes · '+[1+'/'+x,y+'/'+x].join(' and '),result:upper?'O(n log n) · tight when the toll is Θ(n)':'Θ(n log n)',reason:'Children have sizes that sum to the parent size. The full early levels cost '+(upper?'at most O(n)':'n')+' each. The shortest branch has depth about log'+x+' n and the longest about log base '+(x+'/'+y)+' of n. '+(upper?'There are O(log n) levels and each costs O(n). A matching lower bound requires a sufficiently large toll, such as Θ(n).':'The full levels give Ω(n log n). Each later level costs at most n, giving O(n log n).')+' This split needs a recurrence tree or another unequal-split method.',levels:[[0,'n',upper?'O(n)':'n'],[1,'n/'+x+' + '+y+'n/'+x,upper?'O(n)':'n'],[2,'n/'+x*x+' + '+y+'n/'+x*x+' + '+y+'n/'+x*x+' + '+y*y+'n/'+x*x,upper?'O(n)':'n'],['Full early levels','Sizes sum to n',upper?'O(n) per level':'n per level'],['After first leaves','Some branches have stopped','At most O(n) per level']]});
const linTree=(a,b,k=1)=>recurrence({a,b,toll:k===1?'n':k+'·n',caption:'Balanced recursive split',result:'Θ(n log n)',reason:'Here a=b='+a+', so n^(log_b a)=n. The toll is '+k+'n and Master case 2 applies. Every internal level costs '+k+'n and there are log'+b+' n such levels. For a unit base cost and n a power of '+b+', T(n)=n+'+k+'n log'+b+' n.',levels:[[0,1,k+'n'],[1,a,k+'n'],[2,a*a,k+'n'],['d',a+'ᵈ',k+'n'],['log'+b+' n','n','n if T(1)=1']]});
const mergeSort='Compare the heads of the sorted ranges, output the smaller, and advance its pointer. Append either leftover range. Each element moves once, so the merge takes Θ(n).';
const quick='If the pivot is always extreme, the child sizes are 0 and n−1. Thus T(n)=T(n−1)+Θ(n)=Θ(n²) by summing the partition costs. A uniformly random pivot gives expected Θ(n log n), while its worst-case choice sequence is still quadratic.';
const randomQS=answer('Expected Θ(n log n) · worst Θ(n²)','Choose the pivot uniformly from the active range, swap it to the end and apply Lomuto. Recurse on the two remaining ranges.')+code('quick(A, l, r):\n  if l >= r: return\n  swap(A[random_integer(l,r)], A[r])\n  p = partition(A,l,r)\n  quick(A,l,p-1)\n  quick(A,p+1,r)')+para('For sorted ranks i<j, they meet only if either endpoint is the first pivot among ranks i…j. That has probability 2/(j−i+1). Summing over pairs gives 2∑₍d=1₎ⁿ⁻¹(n−d)/(d+1)=Θ(n log n). Extreme pivots at every call give Θ(n²).');
const dpLcs=(x,y)=>'Use dynamic programming to find a longest common subsequence of X = '+x+' and Y = '+y+'. Include the table and recovery.';
const dims=(p)=>'Find the minimum scalar multiplications and optimal parentheses for matrix dimensions '+p.slice(0,-1).map((x,i)=>x+'×'+p[i+1]).join(', ')+'.';
const weighted=(labels,w)=>labels.map((k,i)=>k+':'+w[i]).join(', ');
const mw=(v,w)=>v.map((x,i)=>letters[i]+':('+x+','+w[i]+')').join(', ');
const addPrefix=(r,s)=>({...r,html:para(s)+r.html});
const addEnd=(r,s)=>({...r,html:r.html+s});
add('1(a)',S,1,'A heapsort snapshot shows 16, 14, 15, 10, 12, 27, 28. How many times has the heap root been heapified?','Two extraction rounds for the seven printed entries','The prefix [16,14,15,10,12] is a max heap and the sorted suffix [27,28] contains the two extracted maxima. If you count the initial BUILD-MAX-HEAP call at the root, that makes three top-level calls. The text says eight entries but only seven are printed, so a literal eight-element trace cannot be recovered.');
add('1(b)',S,1,'Give quicksort’s worst-case recurrence and running time.','Option (b) · Θ(n²)',quick);
add('1(c)',R,2,'Solve T(n) = 7T(n/2) + 3n² + 2.',recurrence({a:7,b:2,toll:'3n²+2',depth:1,caption:'Seven-way split',result:'Θ(n^(log₂ 7))',reason:'f(n)=Θ(n²) is polynomially smaller than n^(log₂ 7), since log₂ 7≈2.807. Master case 1. Ignoring the additive 2, level work multiplies by 7/4, so the bottom dominates.',levels:[[0,1,'3n²+2'],[1,7,'(21/4)n²+14'],['d','7ᵈ','3n²(7/4)ᵈ+2·7ᵈ']]}));
add('1(d)',A,2,'Order n^√n, 2ⁿ, (1.000001)ⁿ and n¹⁰2^(n/2) by decreasing growth.','2ⁿ > n¹⁰2^(n/2) > (1.000001)ⁿ > n^√n','Take natural logs. The first three have leading linear coefficients ln 2, (ln 2)/2 and ln 1.000001. The last logarithm, √n ln n, is o(n).');
add('1(e)',C,2,'If a polynomial-time algorithm finds the largest clique, how do P, NP and NPC relate?','Option (C) · P = NP, with NPC inside that class','Compare the returned maximum size with k to solve the NP-complete decision CLIQUE problem in polynomial time. This collapses P and NP. The empty and universal languages remain outside NPC under standard many-one reductions, so NPC is a proper subset when those languages are included.');
add('1(f)',D,2,dims([20,15,30,5,40]),matrixChain([20,15,30,5,40]));
add('1(g)',D,2,'Which of QPRR, PQRR and QPQR are LCSs of QPQRR and PQPRQRP?',addPrefix(lcs('QPQRR','PQPRQRP'),'Option (d). All three are subsequences of both strings and have the maximum length 4.'));
add('1(h)',C,3,'If A reduces to NP-complete B in polynomial time, what follows?','A ∈ NP','Compute the reduction, then run B’s verifier on the resulting instance and certificate. NP-hardness requires a reduction in the opposite direction. The listed “A is in NP but not NP-complete” adds a claim the premise cannot justify. A could be B itself.');
add('1(i)',G,3,'Find Huffman codes for A–F with probabilities 1/2, 1/4, 1/8, 1/16, 1/32, 1/32.',addPrefix(huffman([...letters.slice(0,6).toUpperCase()],[16,8,4,2,1,1]),'Choose the option with codeword lengths 1, 2, 3, 4, 5 and 5. A valid ordering is 0, 10, 110, 1110, 11110, 11111.'));
add('1(j)',D,3,'Which listed algorithm uses dynamic programming?',floydName);
add('2(a)',D,3,dims([5,10,3,12,5,50,6])+' Give the recurrence and complexity.',matrixChain([5,10,3,12,5,50,6]));
add('2(b)',D,3,dpLcs('ababaabaa','aababaab'),lcs('ababaabaa','aababaab'));
const fixedTree=treeDrawing({label:'root',edges:[0,1],children:[{label:'0',edges:[0,1],children:[{label:'00',edges:[0,1],children:[{label:'A',sub:'000'},{label:'B',sub:'001'}]},{label:'01',edges:[0,1],children:[{label:'C',sub:'010'},{label:'E',sub:'011'}]}]},{label:'1',edges:[0],children:[{label:'10',edges:[0],children:[{label:'f',sub:'100'}]}]}]},'Fixed-width decoding tree',{note:'Unused prefixes and unused branches are omitted.'});
add('3(a)',G,4,'Draw fixed and Huffman decoding trees for A:14, B:19, C:40, E:15, f:20. Compare encoded lengths.',addEnd(huffman(['A','B','C','E','f'],[14,19,40,15,20]),fixedTree));
